<style>
.back-leg {
  animation: swing-back 1.4s ease-in-out infinite alternate;
  transform-box: fill-box;
  transform-origin: 50% 0%; /* hip point */
}
.front-leg {
  animation: swing-front 1.4s ease-in-out infinite alternate;
  transform-box: fill-box;
  transform-origin: 50% 10%; /* hip point */
}

@keyframes swing-back {
  from {
    transform: rotate(-40deg) translateY(10%);
  }
  to {
    transform: rotate(0deg);
  }
}
@keyframes swing-front {
  from {
    transform: rotate(35deg) translateY(5%);
  }
  to {
    transform: rotate(-2deg);
  }
}
.front-wheel {
  transform-box: fill-box;
  transform-origin: 42% 50%;
  animation: spin 2s linear infinite;
}
.back-wheel {
  transform-box: fill-box;
  transform-origin: 42% 50%;
  animation: spin 2s linear infinite;
}
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

.walker {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 15%; /* however wide you want the character */
  animation: walk-across 25s linear infinite;
}

@keyframes walk-across {
  from {
    transform: translateX(-100%);
  } /* fully off-screen left */
  to {
    transform: translateX(calc(100vw + 100%));
  } /* fully off-screen right */
}
</style>
